My suspicion is that https://github.com/kubernetes/client-go/blob/v0.36.2/tools/remotecommand/websocket.go#L271 the error path here after failing to set deadline should call `closeAllStreamReaders` as do the other paths. 



### What did you expect to happen?

No leaks are found. 

### How can we reproduce it (as minimally and precisely as possible)?

Something like this:
```go
package remotecommand

// Place this file in staging/src/k8s.io/client-go/tools/remotecommand/ and run:
//
//	go test ./tools/remotecommand/ -run 'TestWebSocketClient_(InitialSetReadDeadlineError|PipeTransportPeerClosedBeforeReadLoop)' -count=1 -v

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"runtime/pprof"
	"sync"
	"testing"
	"time"

	gwebsocket "github.com/gorilla/websocket"

	"k8s.io/apimachinery/pkg/util/remotecommand"
	"k8s.io/streaming/pkg/httpstream/wsstream"
)

func TestWebSocketClient_InitialSetReadDeadlineError(t *testing.T) {
	injected := errors.New("injected SetReadDeadline failure")
	err := runReadDeadlineRepro(t, func(c net.Conn) net.Conn {
		return &setReadDeadlineErrConn{Conn: c, err: injected}
	})
	if err == nil {
		t.Fatalf("expected StreamWithContext to return an error, got nil")
	}
	t.Logf("StreamWithContext returned: %v", err)
}

func TestWebSocketClient_PipeTransportPeerClosedBeforeReadLoop(t *testing.T) {
	err := runReadDeadlineRepro(t, newStoreAndForwardPipe)
	// All server frames are buffered client side, so success would be ideal.
	// At minimum StreamWithContext must return.
	t.Logf("StreamWithContext returned: %v", err)
}

// runReadDeadlineRepro runs a stdout+stderr exec against a server that
// finishes immediately, with the client's net.Conn wrapped by wrap.
func runReadDeadlineRepro(t *testing.T, wrap func(net.Conn) net.Conn) error {
	server := readDeadlineReproServer(t)
	rt := &readDeadlineReproTransport{wrap: wrap}
	exec := &wsStreamExecutor{
		transport:         rt,
		upgrader:          rt,
		method:            "GET",
		url:               server.URL + "?stdout=true&stderr=true",
		protocols:         []string{remotecommand.StreamProtocolV5Name},
		heartbeatPeriod:   pingPeriod,
		heartbeatDeadline: pingReadDeadline,
	}

	var stdout, stderr bytes.Buffer
	errCh := make(chan error, 1)
	go func() {
		// Background ctx: the caller is still waiting, e.g. a proxy whose
		// client is still connected.
		errCh <- exec.StreamWithContext(context.Background(), StreamOptions{
			Stdout: &stdout,
			Stderr: &stderr,
		})
	}()

	select {
	case err := <-errCh:
		return err
	case <-time.After(10 * time.Second):
		t.Fatalf("StreamWithContext did not return within %v; goroutineleak profile:\n\n%s",
			10*time.Second, goroutineLeakProfile(t))
		return nil
	}
}

// readDeadlineReproServer behaves like a command that exits immediately
// (`sh -c 'echo hello >&2'`): stderr, a Success status, a normal close.
func readDeadlineReproServer(t *testing.T) *httptest.Server {
	upgrader := gwebsocket.Upgrader{
		CheckOrigin:  func(r *http.Request) bool { return true },
		Subprotocols: []string{remotecommand.StreamProtocolV5Name},
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		conn, err := upgrader.Upgrade(w, req, nil)
		if err != nil {
			t.Errorf("unable to upgrade: %v", err)
			return
		}
		defer conn.Close() //nolint:errcheck
		_ = conn.WriteMessage(gwebsocket.BinaryMessage, append([]byte{remotecommand.StreamStdErr}, "hello\n"...))
		_ = conn.WriteMessage(gwebsocket.BinaryMessage, append([]byte{remotecommand.StreamErr}, `{"metadata":{},"status":"Success"}`...))
		_ = conn.WriteControl(gwebsocket.CloseMessage,
			gwebsocket.FormatCloseMessage(gwebsocket.CloseNormalClosure, ""), time.Now().Add(time.Second))
	}))
	t.Cleanup(server.Close)
	return server
}

// readDeadlineReproTransport is both the http.RoundTripper and the
// websocket.ConnectionHolder of a wsStreamExecutor, so the test can wrap the
// client's net.Conn.
type readDeadlineReproTransport struct {
	wrap func(net.Conn) net.Conn
	conn *gwebsocket.Conn
}

func (rt *readDeadlineReproTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	dialer := gwebsocket.Dialer{
		NetDialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			c, err := (&net.Dialer{}).DialContext(ctx, network, addr)
			if err != nil {
				return nil, err
			}
			return rt.wrap(c), nil
		},
		Subprotocols:    req.Header[wsstream.WebSocketProtocolHeader],
		ReadBufferSize:  rt.DataBufferSize() + 1024,
		WriteBufferSize: rt.DataBufferSize() + 1024,
	}
	u := *req.URL
	u.Scheme = "ws"
	conn, resp, err := dialer.DialContext(req.Context(), u.String(), nil)
	if err != nil {
		return nil, err
	}
	rt.conn = conn
	return resp, nil
}

func (rt *readDeadlineReproTransport) DataBufferSize() int          { return 32 * 1024 }
func (rt *readDeadlineReproTransport) Connection() *gwebsocket.Conn { return rt.conn }

// setReadDeadlineErrConn fails every SetReadDeadline call. The gorilla client
// handshake only calls SetDeadline, so the first SetReadDeadline comes from
// readDemuxLoop.
type setReadDeadlineErrConn struct {
	net.Conn
	err error
}

func (c *setReadDeadlineErrConn) SetReadDeadline(time.Time) error { return c.err }

// storeAndForwardPipe exposes a TCP conn to the client through net.Pipe.
type storeAndForwardPipe struct {
	net.Conn
	peerClosed chan struct{}
	once       sync.Once
}

func newStoreAndForwardPipe(tcp net.Conn) net.Conn {
	local, remote := net.Pipe()
	p := &storeAndForwardPipe{Conn: local, peerClosed: make(chan struct{})}
	go func() { _, _ = io.Copy(tcp, remote) }() // client -> server
	go func() {
		data, _ := io.ReadAll(tcp) // server -> client, until the server hangs up
		_, _ = remote.Write(data)
		_ = remote.Close()
		_ = tcp.Close()
		close(p.peerClosed)
	}()
	return p
}

func (p *storeAndForwardPipe) SetReadDeadline(t time.Time) error {
	p.once.Do(func() {
		select {
		case <-p.peerClosed:
		case <-time.After(10 * time.Second / 2):
		}
	})
	return p.Conn.SetReadDeadline(t)
}

// goroutineLeakProfile returns the goroutineleak profile in debug=1 text form.
// The profile is on by default in Go 1.27; on Go 1.26 it needs
// GOEXPERIMENT=goroutineleakprofile.
func goroutineLeakProfile(t *testing.T) string {
	t.Helper()
	p := pprof.Lookup("goroutineleak")
	if p == nil {
		return "(goroutineleak profile unavailable: needs Go 1.27+, or Go 1.26 with GOEXPERIMENT=goroutineleakprofile)"
	}
	var buf bytes.Buffer
	if err := p.WriteTo(&buf, 1); err != nil {
		return fmt.Sprintf("(writing goroutineleak profile: %v)", err)
	}
	return buf.String()
}
